<script lang="ts">
 import { untrack } from 'svelte';
 import { PaneGroup, Pane, PaneResizer } from 'paneforge';
 import { createVirtualizer } from '@tanstack/svelte-virtual';
 import { Check, ChevronLeft, ChevronRight, CircleHelp, Copy, FileText, Maximize2, Minimize2, Minus, Plus, RefreshCw, RotateCcw, ZoomIn, ZoomOut } from 'lucide-svelte';
 import { api, type ApiElement, type CatalogEntry, bboxOf, pageOf, field, geometryOf } from './lib/api';
 import { serializeFeedback, type FeedbackPacket } from './lib/feedback';
 import { loadPdf, pdfScale, type PdfFit } from './lib/pdf';
 import { bboxToViewportStyle, type PdfViewportTransform } from './lib/pdfOverlay';
 let split=$state('train'), docs=$state<CatalogEntry[]>([]), documentId=$state(''), documentData=$state<any>(null), candidate=$state<ApiElement[]>([]), reference=$state<ApiElement[]>([]), evaluation=$state<any>(null);
 let loading=$state(false), error=$state(''), selectedId=$state(''), page=$state(1), zoom=$state(1), fitMode=$state<PdfFit>('width'), comment=$state(''); let canvas=$state<HTMLCanvasElement>(); let pdfHost=$state<HTMLDivElement|null>(null); let viewport=$state<PdfViewportTransform|null>(null); let listEl=$state<HTMLDivElement|null>(null); let activePane=$state('source'); let maximized=$state('');
 const rowHeight=76; const virtualizer=createVirtualizer({count:0,getScrollElement:()=>listEl,estimateSize:()=>rowHeight,overscan:8});
 $effect(()=>{const count=candidate.length;const scrollElement=listEl;untrack(()=>$virtualizer.setOptions({...$virtualizer.options,count,getScrollElement:()=>scrollElement,estimateSize:()=>rowHeight}))}); let pdf=$state<any>(null); let pdfLoading=$state(false); let copied=$state(false); let copyError=$state(''); let collapsed=$state<Record<string,boolean>>({});
 const selectedCandidate=$derived(candidate.find(x=>idOf(x)===selectedId)); const selectedIndex=$derived(candidate.findIndex(x=>idOf(x)===selectedId)); const selectedAlignment=$derived(selectedIndex>=0 ? evaluation?.alignments?.find((a:any)=>a.candidate_index===selectedIndex) : undefined); const selectedReference=$derived(selectedAlignment ? reference[selectedAlignment.reference_index] : reference.find(x=>idOf(x)===selectedId)); const selected=$derived(selectedCandidate??selectedReference); const selectedBox=$derived(bboxOf(selected)); const selectedGeometry=$derived(geometryOf(selected)); const selectedPage=$derived(pageOf(selected)); const metricLabel=$derived(evaluation?.metrics ? `F1 ${(evaluation.metrics.element_f1*100).toFixed(1)}% · IoU ${(evaluation.metrics.mean_geometry_iou*100).toFixed(1)}%` : 'evaluation pending');
 function idOf(x:ApiElement){return String(field(x,'element_id',field(x,'id','unknown')))} function textOf(x:ApiElement){return String(field(x,'text',field(x,'content',field(x,'markdown',''))))} function kindOf(x:ApiElement){return String(field(x,'element_type',field(x,'type','element')))}
 async function reload(){loading=true;error='';docs=[];candidate=[];reference=[];evaluation=null;try{const out=await api.documents(split);docs=out.documents||[];const preferred=docs.find(entry=>entry.original_source.available&&entry.candidate.available&&entry.reference.available)??docs.find(entry=>entry.original_source.available)??docs[0];documentId=preferred?.document.id||'';if(!documentId){error='No documents are available for this split.';return}await loadDocument()}catch(e){error=e instanceof Error?e.message:'Unable to load comparison catalog.'}finally{loading=false}}
 async function loadDocument(){if(!documentId)return;loading=true;error='';candidate=[];reference=[];evaluation=null;selectedId='';try{const detail=await api.document(documentId);documentData=detail;const [cand,ref,evalOut]=await Promise.all([detail.candidate?.available?api.elements(documentId,'candidate'):Promise.resolve(null),detail.reference?.available?api.elements(documentId,'reference'):Promise.resolve(null),detail.candidate?.available&&detail.reference?.available?api.evaluation(documentId):Promise.resolve(null)]);candidate=cand?.elements||[];reference=ref?.elements||[];evaluation=evalOut;selectedId=candidate[0]?idOf(candidate[0]):reference[0]?idOf(reference[0]):'';page=pageOf(candidate[0]||reference[0])}catch(e){error=e instanceof Error?e.message:'Comparison data is unavailable.'}finally{loading=false}}
 function choose(x:ApiElement){selectedId=idOf(x);const p=pageOf(x);if(Number.isFinite(p)&&p>0)page=p}
 let renderTask:any; let pdfGeneration=0; let loadedDocumentId=''; let resizeObserver:ResizeObserver|undefined;
 async function renderPdf(){if(!canvas||!pdfHost||!documentId)return;const generation=++pdfGeneration;renderTask?.cancel?.();pdfLoading=true;try{if(loadedDocumentId!==documentId){pdf?.destroy?.();pdf=await loadPdf(`/comparison/documents/${encodeURIComponent(documentId)}/source/original`);loadedDocumentId=documentId}if(generation!==pdfGeneration)return;page=Math.min(page,pdf.numPages);const p=await pdf.getPage(page);const base=p.getViewport({scale:1,rotation:selectedGeometry.rotation});const styles=getComputedStyle(pdfHost!);const horizontalPadding=parseFloat(styles.paddingLeft)+parseFloat(styles.paddingRight);const verticalPadding=parseFloat(styles.paddingTop)+parseFloat(styles.paddingBottom);const availableWidth=Math.max(1,pdfHost!.clientWidth-horizontalPadding);const availableHeight=Math.max(1,pdfHost!.clientHeight-verticalPadding);const scale=pdfScale(fitMode,base.width,base.height,availableWidth,availableHeight,zoom);const view=p.getViewport({scale});viewport={width:view.width,height:view.height,transform:[...view.transform] as PdfViewportTransform['transform']};const outputScale=window.devicePixelRatio||1;canvas.style.width=`${view.width}px`;canvas.style.height=`${view.height}px`;canvas.width=Math.ceil(view.width*outputScale);canvas.height=Math.ceil(view.height*outputScale);renderTask=p.render({canvasContext:canvas.getContext('2d')!,viewport:view,transform:outputScale!==1?[outputScale,0,0,outputScale,0,0]:undefined});await renderTask.promise}catch(e){if((e as Error)?.name!=='RenderingCancelledException')error=e instanceof Error?`Source PDF unavailable: ${e.message}`:'Source PDF unavailable.'}finally{pdfLoading=false}}
 $effect(()=>{documentId;page;zoom;fitMode;selectedGeometry.rotation;canvas;pdfHost;untrack(()=>{resizeObserver?.disconnect();if(pdfHost){resizeObserver=new ResizeObserver(()=>void renderPdf());resizeObserver.observe(pdfHost)}void renderPdf()})});
 $effect(()=>()=>{resizeObserver?.disconnect();renderTask?.cancel?.();pdf?.destroy?.()});
 function toggle(name:string){collapsed[name]=!collapsed[name];localStorage.setItem('pdf2md-pane-state',JSON.stringify(collapsed))} function maximize(name:string){maximized=maximized===name?'':name;localStorage.setItem('pdf2md-pane-mode',maximized)} function restore(){try{collapsed=JSON.parse(localStorage.getItem('pdf2md-pane-state')||'{}');maximized=localStorage.getItem('pdf2md-pane-mode')||''}catch{collapsed={};maximized=''}}
 function keyHandler(event:KeyboardEvent){if((event.metaKey||event.ctrlKey)&&event.key==='Enter'){event.preventDefault();copyPacket();return}if(event.target instanceof HTMLInputElement||event.target instanceof HTMLTextAreaElement||event.target instanceof HTMLSelectElement)return;const index=candidate.findIndex(x=>idOf(x)===selectedId);if(event.key==='j'||event.key==='ArrowDown'){event.preventDefault();const next=candidate[Math.min(candidate.length-1,index+1)];if(next)choose(next)}else if(event.key==='k'||event.key==='ArrowUp'){event.preventDefault();const next=candidate[Math.max(0,index-1)];if(next)choose(next)}else if(event.key==='ArrowLeft'){event.preventDefault();page=Math.max(1,page-1)}else if(event.key==='ArrowRight'){event.preventDefault();page=Math.min(pdf?.numPages||page+1,page+1)}else if(event.key.toLowerCase()==='c'){event.preventDefault();copyPacket()}}
 function jsonFor(x:ApiElement|undefined){return x?.element??null}
 async function copyPacket(){copyError='';if(!selected){copyError='Select an element first.';return}const packet:FeedbackPacket={pdfPath:documentData?.document?.metadata?.original_path||documentData?.document?.local_path||`/comparison/documents/${encodeURIComponent(documentId)}/source/original`,split,page:selectedPage||null,bbox:selectedBox||null,candidate:selectedCandidate?{id:idOf(selectedCandidate),json:jsonFor(selectedCandidate),rendered:selectedCandidate.canonical_rendering||textOf(selectedCandidate)}:null,reference:selectedReference?{id:idOf(selectedReference),json:jsonFor(selectedReference),rendered:selectedReference.canonical_rendering||textOf(selectedReference)}:null,alignment:selectedAlignment?`candidate_index=${selectedAlignment.candidate_index}; reference_index=${selectedAlignment.reference_index}; score=${selectedAlignment.score}`:'unmatched candidate',comment};try{await navigator.clipboard.writeText(serializeFeedback(packet));copied=true;setTimeout(()=>copied=false,1800)}catch(e){copyError=e instanceof Error?`Clipboard failed: ${e.message}`:'Clipboard permission denied.'}}
 restore();reload();
</script>
<svelte:head><title>Provenance Workbench · PDF2MD</title></svelte:head><svelte:window onkeydown={keyHandler} />
<div class="grid h-screen min-h-0 grid-rows-[35px_minmax(0,1fr)_auto] bg-slate-100 text-slate-800">
<header class="hidden"><div class="flex items-center gap-2"><span class="grid size-7 place-items-center rounded bg-slate-800 text-sm font-bold text-white">⌘</span><div class="leading-none"><strong class="font-mono text-sm tracking-widest">PDF<span class="text-cobalt">2</span>MD</strong></div></div><div class="ml-auto flex items-center gap-2"><details class="shortcut-help"><summary class="grid size-7 list-none place-items-center rounded border border-slate-300" aria-label="Keyboard shortcuts"><CircleHelp size={15}/></summary><div class="shortcut-popover"><b>Keyboard shortcuts</b><span>J / K · select element</span><span>← / → · change page</span><span>⌘/Ctrl + Enter · copy packet</span></div></details></div></header>
<section class="flex h-[35px] min-w-0 items-center gap-2 border-b border-slate-300 bg-white px-3"><div class="flex shrink-0 items-center gap-1"><span class="grid size-5 place-items-center rounded bg-slate-800 text-[10px] font-bold text-white">⌘</span><strong class="font-mono text-[11px] tracking-widest">PDF<span class="text-cobalt">2</span>MD</strong></div><select class="max-w-[34vw] border-0 bg-transparent font-mono text-[11px]" bind:value={documentId} onchange={loadDocument} aria-label="Document"><option value="">Select document</option>{#each docs as entry}<option value={entry.document.id}>{entry.document.id}</option>{/each}</select><select class="border-0 bg-transparent font-mono text-[11px]" bind:value={split} onchange={reload} aria-label="Split"><option>validation</option><option>train</option><option>test</option></select><span class="hidden min-w-0 flex-1 font-mono text-[9px] text-slate-500 sm:inline">C {candidate.length} · R {reference.length} · {metricLabel}</span><span class="font-mono text-[9px] text-emerald-700">{loading?'…':'●'}</span><button class="grid size-6 shrink-0 place-items-center" onclick={reload} aria-label="Refresh" title="Refresh"><RefreshCw size={13}/></button><button class="grid size-6 shrink-0 place-items-center" onclick={copyPacket} aria-label="Copy evidence packet" title="Copy evidence packet">{#if copied}<Check size={13}/>{:else}<Copy size={13}/>{/if}</button><details class="shortcut-help"><summary class="grid size-6 list-none place-items-center" aria-label="Keyboard shortcuts" title="Keyboard shortcuts"><CircleHelp size={13}/></summary><div class="shortcut-popover"><b>Shortcuts</b><span>J/K select · ←/→ page</span><span>⌘/Ctrl+Enter copy</span></div></details></section>
