}/>{:else}<RotateCcw size={12}/>{/if}<span class="hidden lg:inline">{mode[1]}</span></button>{/each}<button onclick={()=>{fitMode='actual';zoom=Math.max(.25,zoom-.1)}} aria-label="Zoom out" title="Zoom out"><ZoomOut size={13}/></button><span>{Math.round(zoom*100)}%</span><button onclick={()=>{fitMode='actual';zoom=Math.min(5,zoom+.1)}} aria-label="Zoom in" title="Zoom in"><ZoomIn size={13}/></button><button onclick={()=>{fitMode='actual';zoom=1}} aria-label="Reset zoom" title="Reset zoom">1:1</button><button class="ml-1" onclick={()=>toggle('source')} aria-label="Minimize source" title="Minimize source">{#if collapsed.source}<Plus size={13}/>{:else}<Minus size={13}/>{/if}</button><button onclick={()=>maximize('source')} aria-label="Maximize or restore source" title="Maximize or restore source">{#if maximized==='source'}<Minimize2 size={13}/>{:else}<Maximize2 size={13}/>{/if}</button></div>{#if !collapsed.source}<div bind:this={pdfHost} class="min-h-0 flex-1 overflow-auto bg-slate-100 p-4"><div class="flex min-h-full justify-center"><div class="canvas-wrap relative inline-block bg-white shadow"><canvas bind:this={canvas} aria-label={`Source PDF page ${page}`}></canvas>{#if pdfLoading}<span class="absolute inset-0 grid place-items-center bg-white/70 font-mono text-[10px]">Rendering PDF…</span>{/if}{#if selectedBox&&viewport}{@const overlay=bboxToViewportStyle(selectedBox,selectedGeometry.height,viewport)}{#if overlay}<div class="bbox-overlay" style={`left:${overlay.left}px;top:${overlay.top}px;width:${overlay.width}px;height:${overlay.height}px`}><span>{idOf(selected!)} · selected</span></div>{/if}{/if}</div></div></div>{:else}<div class="grid flex-1 place-items-center font-mono text-xs text-slate-500">Source minimized. <button class="text-cobalt underline" onclick={()=>toggle('source')}>Restore</button></div>{/if}</section></Pane><PaneResizer/><Pane defaultSize={35} minSize={20}><section class:maximized={maximized==='candidate'} class:mobile-hidden={activePane!=='candidate'} class="pane flex h-full min-h-0 min-w-0 flex-col overflow-hidden border border-slate-300 bg-white">{@render PaneHeader("02", "CANDIDATE · pdf2md", `Parser structure · ${candidate.length}`, "candidate", true)}{#if !collapsed.candidate}<div class="element-list min-h-0 flex-1 overflow-auto p-1" bind:this={listEl} role="listbox" aria-label="Candidate elements"><div style={`height:${$virtualizer.getTotalSize()}px;position:relative`}>{#each $virtualizer.getVirtualItems() as row (row.key)}{@const item=candidate[row.index]}<button class:selected={idOf(item)===selectedId} class="absolute left-0 flex h-[76px] w-full cursor-pointer gap-2 overflow-hidden border-b border-slate-200 border-l-2 border-transparent px-2 py-2 text-left hover:border-l-slate-400 hover:bg-slate-50 data-[selected=true]:border-l-cobalt data-[selected=true]:bg-blue-50" data-selected={idOf(item)===selectedId} onclick={()=>choose(item)} role="option" aria-selected={idOf(item)===selectedId} aria-label={`Select ${idOf(item)} and locate it in the source PDF`} title="Select and locate in source PDF" style={`top:${row.start}px`}><span class="grid size-6 shrink-0 place-items-center border border-slate-300 font-mono text-xs text-slate-500">{kindOf(item).slice(0,1).toUpperCase()}</span><span class="min-w-0 flex-1"><span class="flex min-w-0 items-center gap-2 truncate"><b class="font-mono text-[10px]">{idOf(item)}</b><span class="truncate font-mono text-[10px] text-slate-400">{kindOf(item)}</span>{#if idOf(item)===selectedId}<span class="ml-auto inline-flex shrink-0 items-center gap-1 font-mono text-[9px] text-cobalt"><Check size={11}/> selected</span>{/if}</span><span class="mt-1 block truncate text-xs text-slate-700">{textOf(item)||'(no rendered text)'}</span><span class="mt-1 block truncate font-mono text-[9px] text-slate-400">page {pageOf(item)} · bbox {bboxOf(item)?.join(', ')||'unavailable'}</span></span></button>{/each}</div>{#if !candidate.length}<div class="grid h-full place-items-center font-mono text-xs text-slate-500">Candidate unavailable.</div>{/if}</div>{#if selectedCandidate}<section class="h-[42%] min-h-32 shrink-0 overflow-auto border-t-2 border-cobalt bg-white" aria-live="polite"><div class="sticky top-0 z-10 flex h-7 items-center border-b border-slate-200 bg-blue-50 px-2 font-mono text-[9px] text-cobalt"><Check size={11}/><b class="ml-1">SELECTED CANDIDATE</b><span class="ml-2 truncate text-slate-600">{idOf(selectedCandidate)}</span></div><div class="p-2"><div class="mb-1 font-mono text-[9px] text-slate-500">CANONICAL OUTPUT</div><div class="mb-3 border border-blue-200 bg-blue-50 p-2 text-xs leading-relaxed">{selectedCandidate.canonical_rendering||textOf(selectedCandidate)||'(empty canonical output)'}</div><div class="mb-1 font-mono text-[9px] text-slate-500">EXACT JSON</div><pre class="overflow-auto border-l-2 border-cobalt bg-slate-50 p-2 font-mono text-[10px] leading-relaxed">{JSON.stringify(jsonFor(selectedCandidate),null,2)}</pre></div></section>{/if}{:else}<div class="grid flex-1 place-items-center font-mono text-xs text-slate-500">Candidate minimized. <button class="text-cobalt underline" onclick={()=>toggle('candidate')}>Restore</button></div>{/if}</section></Pane><PaneResizer/><Pane defaultSize={31} minSize={20}><section class:maximized={maximized==='reference'} class:mobile-hidden={activePane!=='reference'} class="pane flex h-full min-h-0 min-w-0 flex-col overflow-hidden border border-slate-300 bg-white">{@render PaneHeader("03", "REFERENCE · silver / gold", `Canonical structure · ${reference.length}`, "reference", false, true)}{#if !collapsed.reference}{#if selectedReference}<div class="min-h-0 flex-1 overflow-auto p-3"><div class="mb-1 font-mono text-[9px] text-slate-500">EXACT JSON</div><pre class="mb-4 overflow-auto border-l-2 border-teal bg-teal-50 p-2 font-mono text-[10px] leading-relaxed">{JSON.stringify(jsonFor(selectedReference),null,2)}</pre><div class="mb-1 font-mono text-[9px] text-slate-500">CANONICAL OUTPUT</div><div class="border border-teal-200 bg-teal-50 p-2 text-xs leading-relaxed">{selectedReference.canonical_rendering||textOf(selectedReference)||'(empty canonical output)'}</div></div>{:else}<div class="grid flex-1 place-items-center font-mono text-xs text-slate-500">Select a paired element.</div>{/if}{:else}<div class="grid flex-1 place-items-center font-mono text-xs text-slate-500">Reference minimized. <button class="text-cobalt underline" onclick={()=>toggle('reference')}>Restore</button></div>{/if}</section></Pane></PaneGroup></main>{/if}
<footer class="flex max-h-12 min-h-0 items-center gap-3 border-t border-slate-300 bg-slate-50 px-3 py-1.5"><div class="min-w-0 shrink-0"><b class="font-mono text-[9px]">EVIDENCE</b><small class="block max-w-44 truncate font-mono text-[9px] text-slate-500">{selectedId||'no selection'} · p.{selectedPage}</small></div><div class="hidden min-w-0 flex-1 truncate font-mono text-[9px] text-slate-500 lg:block">BBOX {selectedBox?`[${selectedBox.join(', ')}]`:'unavailable'}</div><textarea class="h-7 min-w-0 flex-1 resize-none border border-slate-300 bg-white px-2 py-1 text-[11px]" bind:value={comment} aria-label="Engineer comment" placeholder="Add a reproducible note…"></textarea><button class="inline-flex h-7 shrink-0 items-center gap-1 bg-slate-800 px-2.5 font-mono text-[10px] text-white" onclick={copyPacket}>{#if copied}<Check size={13}/>{:else}<Copy size={13}/>{/if} {copied?'Copied':'Copy'} </button>{#if copyError}<span class="text-[10px] text-red-600" role="alert">{copyError}</span>{/if}</footer></div>
{#snippet PaneHeader(num:string,label:string,title:string,name:string,cobalt=false,teal=false)}<div class="flex h-8 min-h-8 items-center justify-between border-b border-slate-200 bg-slate-50 px-2"><div class="min-w-0 truncate font-mono text-[10px] {cobalt?'text-cobalt':''}{teal?' text-teal':''}">{num} {label} · <b class="font-sans font-semibold text-slate-800">{title}</b></div><div class="flex shrink-0 gap-1"><button class="grid size-6 place-items-center text-slate-500" onclick={()=>toggle(name)} aria-label={`Minimize ${name}`}>{#if collapsed[name]}<Plus size={14}/>{:else}<Minus size={14}/>{/if}</button><button class="grid size-6 place-items-center text-slate-500" onclick={()=>maximize(name)} aria-label={`Maximize or restore ${name}`}>{#if maximized===name}<Minimize2 size={14}/>{:else}<Maximize2 size={14}/>{/if}</button></div></div>{/snippet}
